# Activity selection / non-overlapping intervals: sort by END time.
# Sorting by start or by duration both fail. The argument: finishing earliest
# leaves the most room for everything that follows.
def max_non_overlapping(intervals: list[tuple[int, int]]) -> int:
    intervals.sort(key=lambda iv: iv[1])
    count, last_end = 0, float('-inf')
    for start, end in intervals:
        if start >= last_end:
            count += 1
            last_end = end
    return count

# Merge intervals: sort by START, then extend or append.
def merge(intervals: list[list[int]]) -> list[list[int]]:
    intervals.sort()
    out: list[list[int]] = []
    for iv in intervals:
        if out and iv[0] <= out[-1][1]:
            out[-1][1] = max(out[-1][1], iv[1])
        else:
            out.append(iv[:])
    return out

